function quiz({title,text,options,answer,success,onpass}){open(`<div class="eyebrow">CHECK YOUR UNDERSTANDING</div><h2>${title}</h2><p class="modal-sub">${text}</p><div class="choices">${options.map((x,i)=>`<button data-answer="${i}">${x}</button>`).join('')}</div><div class="feedback" role="status"></div>`);document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(+b.dataset.answer===answer){$('.feedback').innerHTML=success;document.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);const next=document.createElement('button');next.className='primary';next.textContent='Continue →';next.onclick=onpass;$('.feedback').append(document.createElement('br'),next);}else{$('.feedback').textContent='Not quite. '+(answer===0?'Look or listen carefully, then try again.':'Take another look at the explanation and try again.');}});}
function lesson(id){if(id===0){open(`<div class="eyebrow">LESSON 01 · DISCOVER</div><h2>Meet your violin.</h2><p class="modal-sub">A violin has four strings, tuned from lowest to highest: <b>G, D, A, E</b>. The bow makes a string vibrate. The wooden body helps that vibration radiate as sound.</p><div style="height:220px;display:flex;justify-content:center;background:#f0e3f2;border-radius:9px">${violin}</div><p class="modal-sub">The fingerboard sits under the strings. Pressing a string against it shortens the vibrating length and raises its pitch. A violin has no frets.</p><button class="primary" id="check">Try a quick check →</button>`);$('#check').onclick=()=>quiz({title:'Which string sounds lowest?',text:'From lowest to highest, the open strings are G, D, A, E.',options:['G','E','A','D'],answer:0,success:'Exactly. G is the lowest open string.',onpass:()=>{completed(0);close();}});}
if(id===1)rhythm(true);if(id===2)strings(true);if(id===3){open('<div class="eyebrow">LESSON 04 · NOTATION</div><h2>Meet the musical alphabet.</h2><p class="modal-sub">Musical letter names repeat: A, B, C, D, E, F, G, then A again. Notes can sound higher or lower while sharing a letter name.</p><div class="string-board" style="font-size:26px;text-align:center;letter-spacing:10px">A B C D E F G</div><p class="modal-sub">On a staff, notes sit on lines and spaces. In treble clef, the lines from bottom to top are E, G, B, D, F. The spaces are F, A, C, E.</p><button class="primary" id="check">Check what you remember →</button>');$('#check').onclick=()=>quiz({title:'What comes after G?',text:'Choose the next letter name in the repeating musical alphabet.',options:['H','A','F','C'],answer:1,success:'Yes. After G, the musical alphabet returns to A.',onpass:()=>{completed(3);close();}});}
if(id===4)kit(true);if(id===5){if([0,1,2,3,4].some(i=>!state.done.includes(i))){open('<h2>A little preparation first.</h2><p class="modal-sub">Complete the first five lessons before the independent foundation check. You can explore or review them in any order.</p><button class="primary" id="pathGo">Open my pathway →</button>');$('#pathGo').onclick=()=>{close();go('path');};return;}quiz({title:'Remember the strings?',text:'Without a diagram, choose the violin strings from lowest to highest.',options:['E, A, D, G','G, D, A, E','C, G, D, A','A, B, C, D'],answer:1,success:'You remembered the string order. One more check.',onpass:()=>quiz({title:'Read the treble staff.',text:'What is the lowest line of the treble staff?',options:['G','C','E','A'],answer:2,success:'Correct: E. You’ve completed this introductory knowledge pathway. Real-instrument technique is still to come.',onpass:()=>{completed(5);close();}})});}}
